/* From Uiverse.io by igoramos77 - Tags: card */
.__UIV_SCOPE__ .container {
  position: relative;
  height: 300px;
  background: #6c23c0;
  padding: 2rem;
  border-radius: 8px;
  transition: all .25s ease-in-out;
}

.__UIV_SCOPE__ .container:hover {
  box-shadow: 0 4px 50px #00000020;
}

.__UIV_SCOPE__ .container:hover .card {
  transform: translateY(-5%);
}

.__UIV_SCOPE__ .info {
  margin-top: 1rem;
}

.__UIV_SCOPE__ .info h2, .__UIV_SCOPE__ p {
  color: #fff;
  text-align: center;
}

.__UIV_SCOPE__ .card {
  transition: all .25s ease-in-out;
}

.__UIV_SCOPE__ .card input {
  display: none;
}

.__UIV_SCOPE__ .card main {
  position: relative;
}

.__UIV_SCOPE__ .card main a svg {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  border: 4px solid rgb(108, 35, 192);
}

.__UIV_SCOPE__ .card main a {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  background-image: linear-gradient(to right, rgb(23, 122, 250) 20%, rgb(3, 240, 209));
  border-radius: 50%;
  overflow: hidden;
}

.__UIV_SCOPE__ .card main a:hover::after {
  opacity: 1;
}

.__UIV_SCOPE__ .card main a::after {
  content: "Change";
  position: absolute;
  width: 100%;
  height: 35%;
  left: 0px;
  bottom: 0px;
  background-image: linear-gradient(transparent 0%, rgba(108, 35, 192, 0.584) 100%);
  display: flex;
  justify-content: center;
  align-items: center;
  color: rgb(255, 255, 255);
  opacity: 0;
  transition: all 0.2s ease-in-out 0s;
  padding-bottom: 1rem;
}

.__UIV_SCOPE__ .card span {
  position: absolute;
  bottom: 5px;
  right: 5px;
  background: rgb(119, 255, 170);
  width: 35px;
  height: 35px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 4px solid rgb(108, 35, 192);
  color: rgb(108, 35, 192);
}
